create extension if not exists pgcrypto;
create table if not exists governance_policies (id uuid primary key default gen_random_uuid(), name text not null, description text not null, status text not null default 'draft', version integer not null default 1, effective_at timestamptz, created_by uuid, updated_by uuid, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists change_requests (id uuid primary key default gen_random_uuid(), title text not null, description text not null, status text not null default 'draft', submitted_by uuid, submitted_at timestamptz, reviewed_by uuid, reviewed_at timestamptz, review_comments text, rejection_reason text, created_by uuid, updated_by uuid, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists approval_rules (id uuid primary key default gen_random_uuid(), name text not null, required_role text, threshold numeric(14,2), active boolean not null default true, created_by uuid, updated_by uuid, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists feature_lifecycles (id uuid primary key default gen_random_uuid(), name text not null, stage text not null default 'proposed', stage_comments text, owner_id uuid, created_by uuid, updated_by uuid, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists risk_assessments (id uuid primary key default gen_random_uuid(), title text not null, description text, severity text not null, likelihood text, status text not null default 'open', owner_id uuid, mitigation text, created_by uuid, updated_by uuid, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists enterprise_standards (id uuid primary key default gen_random_uuid(), name text not null, description text, status text not null default 'draft', version text, owner_id uuid, created_by uuid, updated_by uuid, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists country_rules (id uuid primary key default gen_random_uuid(), country_code text not null, name text not null, rule_type text, rule_value jsonb not null default '{}', status text not null default 'active', created_by uuid, updated_by uuid, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists partner_requirements (id uuid primary key default gen_random_uuid(), partner_type text not null, name text not null, description text, required boolean not null default true, status text not null default 'active', created_by uuid, updated_by uuid, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists releases (id uuid primary key default gen_random_uuid(), name text not null, version text, description text, status text not null default 'planned', planned_at timestamptz, released_at timestamptz, owner_id uuid, created_by uuid, updated_by uuid, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists decision_registers (id uuid primary key default gen_random_uuid(), title text not null, context text, decision text not null, rationale text, status text not null default 'active', decided_by uuid, decided_at timestamptz, created_by uuid, updated_by uuid, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index if not exists governance_policies_status_idx on governance_policies(status); create index if not exists change_requests_status_idx on change_requests(status); create index if not exists risk_assessments_status_idx on risk_assessments(status); create index if not exists releases_status_idx on releases(status); create index if not exists country_rules_country_idx on country_rules(country_code);
alter table governance_policies enable row level security; alter table change_requests enable row level security; alter table approval_rules enable row level security; alter table feature_lifecycles enable row level security; alter table risk_assessments enable row level security; alter table enterprise_standards enable row level security; alter table country_rules enable row level security; alter table partner_requirements enable row level security; alter table releases enable row level security; alter table decision_registers enable row level security;
create policy governance_authenticated_read on governance_policies for select to authenticated using (true); create policy governance_authenticated_changes on change_requests for select to authenticated using (true); create policy governance_authenticated_approval on approval_rules for select to authenticated using (true); create policy governance_authenticated_features on feature_lifecycles for select to authenticated using (true); create policy governance_authenticated_risks on risk_assessments for select to authenticated using (true); create policy governance_authenticated_standards on enterprise_standards for select to authenticated using (true); create policy governance_authenticated_countries on country_rules for select to authenticated using (true); create policy governance_authenticated_partners on partner_requirements for select to authenticated using (true); create policy governance_authenticated_releases on releases for select to authenticated using (true); create policy governance_authenticated_decisions on decision_registers for select to authenticated using (true);
